    vector<int> differences;
    for (int i = 0; i < n - 1; i++) {
        if ((a[i] & 1) == 0) countEven++;
        else countOdd++;
        if (countEven == countOdd) {
            differences.push_back(abs(a[i] - a[i + 1]));
        }
    }
    int size = differences.size();
    vector<vector<int>> dp(size + 1, vector<int>(w + 1, 0));
    for (int i = 1; i <= size; i++) {
        int val = differences[i - 1];
        for (int j = 1; j <= w; j++) {
            if (val <= j) {
                dp[i][j] = max(1 + dp[i - 1][j - val], dp[i - 1][j]);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }
    cout << dp[size][w] << "\n";
    return 0;
